mapper.update:
update competition_promoted_info
competition_series_id = #{competitionSeriesId}, apply_start_time = #{applyStartTime}, apply_end_time = #{applyEndTime}, promoted_hint = #{promotedHint}, fee = #{fee}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, version = #{version}, del_flag = #{delFlag},
where promoted_id = #{promotedId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM competition_promoted_info p
             LEFT JOIN competition_promoted_apply_info a
                       ON p.competition_series_id = a.competition_series_id
                           AND a.team_code = #{teamCode}
    WHERE p.competition_series_id = #{seriesId} AND a.leader_teacher_id = #{teacherId}
      AND COALESCE(a.apply_status, 0) = 0
      AND NOW() BETWEEN p.apply_start_time AND p.apply_end_time
)

SELECT EXISTS (
    SELECT 1
    FROM competition_promoted_info p
    WHERE p.competition_series_id = #{seriesId}
      AND NOW() BETWEEN p.apply_start_time AND p.apply_end_time
)
